"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["65290"],{24658(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.autorizacao.pedido.termo_exigido","status":409,"titulo":"O perfil passou a exigir o termo de responsabilidade"},"descricao":{"codigo":"uniplus.autorizacao.pedido.termo_exigido","requisitos":["UNI-REQ-0378"],"oQueAconteceu":["O perfil passou a dar acesso a dado pessoal ou sens\xedvel depois da cria\xe7\xe3o do pedido, que n\xe3o tem termo de responsabilidade fixado. O pedido foi devolvido; refa\xe7a-o para aceitar o termo.","Quando o pedido foi criado, o perfil n\xe3o exigia o termo, e por isso nenhuma vers\xe3o foi fixada nem aceita. Na aprova\xe7\xe3o pelo gestor de acessos, o perfil j\xe1 \xe9 protegido, e nenhuma concess\xe3o protegida nasce sem o aceite do termo (ADR-0162 da uniplus-api). A aprova\xe7\xe3o n\xe3o foi registrada e n\xe3o houve concess\xe3o: o pedido foi encerrado como devolvido, e a trilha do pedido registra a devolu\xe7\xe3o por termo exigido. Diferentemente das demais recusas, essa devolu\xe7\xe3o fica gravada."],"comoResolver":["O pedido devolvido n\xe3o volta \xe0 fila. Quem pediu faz um pedido novo do mesmo perfil, que agora fixa a vers\xe3o vigente do termo; a pessoa benefici\xe1ria aceita o termo, depois da verifica\xe7\xe3o do documento quando houver, e o novo pedido segue para o gestor de acessos."],"ondeAparece":["Aprova\xe7\xe3o do pedido de concess\xe3o de acesso pelo gestor de acessos"]},"modulo":{"id":"autorizacao","nome":"Autoriza\xe7\xe3o","assunto":"Pedido"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"418da40321f5e48caae8956b248f9336904d661a"}}')}}]);